-- Denizli catalogue continuation: visitor-worthy places.
insert into public.places (name,category,place_type,city,address,latitude,longitude,slug,short_description,long_description,source_url,external_source,external_id,verified,trust_score,is_active,content_review_status,tags)
select v.name,v.category,v.place_type,'Denizli',v.address,v.lat,v.lon,v.slug,v.short_desc,v.long_desc,v.src,'curated_seed',v.ext,false,85,true,'source_backed',to_jsonb(v.tags)
from (values
('Tabae Antik Kenti','Tarih ve arkeoloji','Antik kent','Kale, Denizli',37.45,29.92,'tabae-antik-kenti','Dağlık arazi üzerindeki antik yerleşim kalıntıları','Tabae, eski ticaret yolları üzerindeki konumu ve dağlık alana yayılan yerleşim izleriyle Denizli çevresinin arkeolojik duraklarındandır.','https://kulturportali.gov.tr/turkiye/denizli/gezilecekyer/tabae-antik-kenti','denizli-tabae-antik-kenti',array['arkeoloji','antik kent']::text[]),
('Herakleia Salbace Antik Kenti','Tarih ve arkeoloji','Antik kent','Vakıf, Tavas, Denizli',37.63,29.04,'herakleia-salbace-antik-kenti','Tavas çevresindeki antik yerleşim kalıntıları','Herakleia Salbace, antik Karia bölgesinin iç kesimlerindeki yerleşimlerden biridir. Ziyaret öncesi erişim koşulları teyit edilmelidir.','https://kulturportali.gov.tr/turkiye/denizli/gezilecekyer/herakleia-salbace-antik-kenti','denizli-herakleia-salbace-antik-kenti',array['arkeoloji','antik kent']::text[]),
('Buldan Dokuma Geleneği','Kültür','Geleneksel el sanatları','Buldan, Denizli',38.05,28.83,'buldan-dokuma-gelenegi','Buldan’ın geleneksel dokumacılığını tanıtan kültürel durak','Buldan, geleneksel dokumacılığı ve tarihî kent dokusuyla bilinir. Bu kayıt tek bir işletmeyi değil, yerel dokuma kültürünü ifade eder.','https://denizli.ktb.gov.tr/','denizli-buldan-dokuma-gelenegi',array['kültür','dokuma']::text[])
) as v(name,category,place_type,address,lat,lon,slug,short_desc,long_desc,src,ext,tags)
where not exists (select 1 from public.places p where p.city='Denizli' and (p.slug=v.slug or p.external_id=v.ext or p.name=v.name));